#!/usr/bin/env node
/* Fixed front-facing membrane capsule with periodic oxygen motion inside.
 * Artwork is generated by GPT. Requires @napi-rs/canvas for offline frame rendering.
 */
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const {createCanvas, loadImage} = require('@napi-rs/canvas');
const {components} = require('./render_marrow_loop.cjs');

function windowGeometry(image, box) {
  const width = box.right - box.left, height = box.bottom - box.top;
  const canvas = createCanvas(width, height), ctx = canvas.getContext('2d');
  ctx.drawImage(image, box.left, box.top, width, height, 0, 0, width, height);
  const pixels = ctx.getImageData(0, 0, width, height).data;
  const seen = new Uint8Array(width * height), queue = new Int32Array(width * height), holes = [];
  for (let start = 0; start < seen.length; start++) {
    if (seen[start] || pixels[start * 4 + 3] >= 96) continue;
    let head = 0, tail = 1, edge = false;
    queue[0] = start; seen[start] = 1;
    const points = [];
    while (head < tail) {
      const point = queue[head++], x = point % width, y = Math.floor(point / width);
      if (!x || !y || x === width - 1 || y === height - 1) edge = true;
      const next = [];
      if (x) next.push(point - 1);
      if (x + 1 < width) next.push(point + 1);
      if (y) next.push(point - width);
      if (y + 1 < height) next.push(point + width);
      if (next.some(index => pixels[index * 4 + 3] >= 96)) points.push({x, y});
      for (const neighbor of next) {
        if (!seen[neighbor] && pixels[neighbor * 4 + 3] < 96) {seen[neighbor] = 1; queue[tail++] = neighbor;}
      }
    }
    if (!edge && tail > 1000) holes.push({area: tail, points});
  }
  const hole = holes.sort((a, b) => b.area - a.area)[0];
  if (!hole) throw new Error('Housing needs a transparent enclosed front window');
  const points = hole.points.sort((a, b) => a.x - b.x || a.y - b.y);
  const cross = (a, b, c) => (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
  const lower = [], upper = [];
  for (const p of points) {while (lower.length >= 2 && cross(lower.at(-2), lower.at(-1), p) <= 0) lower.pop(); lower.push(p);}
  for (const p of points.slice().reverse()) {while (upper.length >= 2 && cross(upper.at(-2), upper.at(-1), p) <= 0) upper.pop(); upper.push(p);}
  const hull = lower.slice(0, -1).concat(upper.slice(0, -1));
  const bounds = {left: Math.min(...hull.map(p => p.x)), top: Math.min(...hull.map(p => p.y)),
    right: Math.max(...hull.map(p => p.x)), bottom: Math.max(...hull.map(p => p.y))};
  return {hull, bounds};
}

function render(image, layers, window, phase) {
  const canvas = createCanvas(512, 512), ctx = canvas.getContext('2d');
  ctx.imageSmoothingEnabled = true; ctx.imageSmoothingQuality = 'high';
  const housing = layers[1], width = housing.right - housing.left, height = housing.bottom - housing.top;
  const scale = 420 / width, x = 46, y = 456 - height * scale;
  const b = window.bounds, w = b.right - b.left, h = b.bottom - b.top;
  const cx = (b.left + b.right) / 2, cy = (b.top + b.bottom) / 2;
  ctx.save(); ctx.translate(x, y); ctx.scale(scale, scale);
  ctx.beginPath();
  window.hull.forEach((p, i) => {
    const px = cx + (p.x - cx) * 1.025, py = cy + (p.y - cy) * 1.025;
    if (i) ctx.lineTo(px, py); else ctx.moveTo(px, py);
  });
  ctx.closePath(); ctx.clip();
  const gas = layers[2], gasWidth = gas.right - gas.left, gasHeight = gas.bottom - gas.top;
  // The chamber's painted cyan interior is a texture behind the rigid window frame.
  ctx.globalAlpha = .975 + .025 * (1 + Math.cos(phase)) / 2;
  ctx.drawImage(image, gas.left + gasWidth * .18, gas.top + gasHeight * .23, gasWidth * .58, gasHeight * .58,
    b.left - 5, b.top - 5, w + 10, h + 10);
  ctx.globalAlpha = 1;
  const groups = [
    {index: 3, u: .34, v: .29, width: .30, phase: 0},
    {index: 4, u: .71, v: .53, width: .27, phase: 2.1},
    {index: 5, u: .36, v: .77, width: .29, phase: 4.2},
  ];
  for (const group of groups) {
    const source = layers[group.index], pw = w * group.width;
    const ph = pw * (source.bottom - source.top) / (source.right - source.left);
    const px = b.left + w * group.u + 1.5 * Math.cos(phase + group.phase);
    const py = b.top + h * group.v + 3.5 * Math.sin(phase + group.phase);
    ctx.drawImage(image, source.left, source.top, source.right - source.left, source.bottom - source.top,
      px - pw / 2, py - ph / 2, pw, ph);
  }
  ctx.restore();
  ctx.drawImage(image, housing.left, housing.top, width, height, x, y, width * scale, height * scale);
  return canvas;
}

async function main() {
  const [source, output] = process.argv.slice(2);
  if (!source || !output || fs.existsSync(output)) throw new Error('Provide a source image and a NEW output directory');
  const image = await loadImage(source), layers = components(image), window = windowGeometry(image, layers[1]);
  fs.mkdirSync(output, {recursive: true});
  fs.copyFileSync(source, path.join(output, 'gpt-source-components.png'));
  fs.writeFileSync(path.join(output, 'layer-bounds.json'), JSON.stringify({layers, window}, null, 2) + '\n');
  const names = ['reference', 'housing', 'oxygen-chamber', 'oxygen-pair-1', 'oxygen-pair-2', 'oxygen-pair-3'];
  layers.forEach((box, index) => {
    const canvas = createCanvas(box.right - box.left, box.bottom - box.top);
    canvas.getContext('2d').drawImage(image, box.left, box.top, canvas.width, canvas.height, 0, 0, canvas.width, canvas.height);
    fs.writeFileSync(path.join(output, names[index] + '.png'), canvas.toBuffer('image/png'));
  });
  const atlas = createCanvas(2560, 2048), frames = [], hashes = [];
  for (let i = 0; i < 20; i++) {
    const phase = 2 * Math.PI * i / 20, canvas = render(image, layers, window, phase);
    const name = `frame-${String(i + 1).padStart(3, '0')}.png`, buffer = canvas.toBuffer('image/png');
    fs.writeFileSync(path.join(output, name), buffer);
    hashes.push(crypto.createHash('sha256').update(buffer).digest('hex'));
    atlas.getContext('2d').drawImage(canvas, i % 5 * 512, Math.floor(i / 5) * 512);
    frames.push({name, duration: 100, rect: {x: i % 5 * 512, y: Math.floor(i / 5) * 512, w: 512, h: 512},
      anchor: {x: .5, y: 456 / 512}, phase});
  }
  const initial = render(image, layers, window, 0).getContext('2d').getImageData(0, 0, 512, 512).data;
  const wrapped = render(image, layers, window, 2 * Math.PI).getContext('2d').getImageData(0, 0, 512, 512).data;
  if (!Buffer.from(initial).equals(Buffer.from(wrapped))) throw new Error('Loop curve does not close exactly');
  fs.writeFileSync(path.join(output, 'spritesheet.png'), atlas.toBuffer('image/png'));
  fs.writeFileSync(path.join(output, 'animation.json'), JSON.stringify({name: '氧气中转站 · 正面方形版', animation: 'idle',
    frameCount: 20, fps: 10, loop: true, durationMs: 2000, width: 512, height: 512, columns: 5, rows: 4,
    spritesheet: 'spritesheet.png', preview: 'preview.webp',
    generatedBy: 'OpenAI image generation for a clean front-facing rounded-square biological membrane capsule; fixed-layer twenty-frame rendering.',
    processing: 'The same soft membrane shell is reused unchanged across all frames; oxygen texture and molecule groups move only inside the membrane.',
    loopCurve: '20 samples of a periodic curve; phase 2π is pixel-identical to phase 0, without duplicating the endpoint.',
    sourceSHA256: crypto.createHash('sha256').update(fs.readFileSync(source)).digest('hex'), frames}, null, 2) + '\n');
  const checks = {frames: 20, uniqueFrames: new Set(hashes).size, durationMs: 2000, exactCycleClosure: true,
    rigidHousingFixed: true, oxygenGroups: 3, windowClipping: true};
  fs.writeFileSync(path.join(output, 'render-checks.json'), JSON.stringify(checks, null, 2) + '\n');
  console.log(JSON.stringify({output, checks, layerCount: layers.length, window: window.bounds}));
}
main().catch(error => {console.error(error.message); process.exit(1);});
